/**
 * Harita Avı'nın il havuzu — Türkiye'nin 81 ili.
 *
 * Sınırlar **Natural Earth** (1:10m admin-1) verisinden üretildi; o veri
 * kamuya açık, telif kısıtı yok. Ham veri projeye girmiyor: koordinatlar
 * eşdikdörtgen izdüşümle (boylam 39° enleme göre daraltılarak) düzleme
 * indirildi, Douglas–Peucker ile sadeleştirildi ve 1000×422 birimlik bir
 * kutuya oturtuldu. Sonuç 5.500 nokta — telefonda akıcı çiziliyor, uygulama
 * çevrimdışı kalıyor.
 *
 * Dosya elle düzenlenmemeli: yeniden üretmek gerekirse aynı boru hattı
 * (indir → ayrıştır → izdüşüm → sadeleştir → ölçekle) tekrarlanmalı.
 */

import type { Zorluk } from './ritim'

/** Haritanın kutusu; SVG `viewBox` bu değerlerle kuruluyor. */
export const HARITA_GENISLIK = 1000
export const HARITA_YUKSEKLIK = 422

export type Il = {
  ad: string
  /** Plaka kodu — tur sonu listesinde ilin yanında görünüyor. */
  plaka: string
  /** İlin ağırlık merkezi; işaret ve çeldirici seçimi buradan. */
  merkez: [number, number]
  /**
   * Kutu birimiyle alan.
   *
   * Soru tipini bu belirliyor: telefonda çok küçük kalan iller "haritada bul"
   * olarak sorulmuyor — Yalova 390 piksellik ekranda altı piksel, orada
   * dokunmak beceriden çok şans olurdu. Onlar işaretlenip adı soruluyor.
   */
  alan: number
  zorluk: Zorluk
  /** SVG yolu; `viewBox` kutusuna göre. */
  yol: string
}

/**
 * "Haritada bul" için en küçük alan.
 *
 * 390 piksel genişliğinde bir ekranda kutu birimi 0,39 piksele denk geliyor;
 * 2000 birim alan yaklaşık 14 piksellik bir şekil demek. Altındakiler parmakla
 * güvenilir biçimde seçilemiyor.
 */
